package org.apache.commons.math.stat.inference;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.ChiSquaredDistribution;
import org.apache.commons.math.distribution.ChiSquaredDistributionImpl;
import org.apache.commons.math.distribution.DistributionFactory;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.MathRuntimeException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ChiSquareTestImpl_chiSquareTest_TriageGen0Test {

    private ChiSquareTestImpl testInstance;

    @Before
    public void setUp() {
        testInstance = new ChiSquareTestImpl();
    }

    /**
     * Test a standard valid contingency table.
     * Expected behavior: Returns a p-value within [0, 1].
     */
    @Test
    public void testChiSquareTest_ValidInput() throws Exception {
        long[][] counts = {
            {10, 20, 30},
            {40, 50, 60}
        };
        // df = (2-1)*(3-1) = 2
        double pValue = testInstance.chiSquareTest(counts);
        assertTrue("p-value should be between 0 and 1", pValue >= 0.0 && pValue <= 1.0);
    }

    /**
     * Test with a 1x1 table.
     * Note: df = (1-1)*(1-1) = 0. 
     * The implementation calculates df = (counts.length - 1) * (counts[0].length - 1).
     * If df is 0, the distribution behavior depends on the internal ChiSquaredDistribution implementation.
     */
    @Test
    public void testChiSquareTest_SingleElementTable() throws Exception {
        long[][] counts = {{10}};
        // df = 0. Most implementations of ChiSquaredDistribution will handle df=0 or throw error.
        // Based on the code: df = (1-1)*(1-1) = 0.
        try {
            double pValue = testInstance.chiSquareTest(counts);
            assertTrue(pValue >= 0.0 && pValue <= 1.0);
        } catch (Exception e) {
            // Acceptable if the distribution doesn't support 0 df
        }
    }

    /**
     * Test with null input.
     * Expected behavior: Throws IllegalArgumentException via checkArray(counts).
     */
    @Test(expected = IllegalArgumentException.class)
    public void testChiSquareTest_NullInput() throws Exception {
        testInstance.chiSquareTest(null);
    }

    /**
     * Test with empty array.
     * Expected behavior: Throws IllegalArgumentException via checkArray(counts).
     */
    @Test(expected = IllegalArgumentException.class)
    public void testChiSquareTest_EmptyArray() throws Exception {
        testInstance.chiSquareTest(new long[0][0]);
    }

    /**
     * Test with uneven row lengths (Ragged array).
     * Expected behavior: checkArray usually checks for null or empty, but if it allows ragged, 
     * df calculation might fail or return unexpected results. 
     * However, standard Apache Commons checkArray throws exception for null/empty.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testChiSquareTest_RaggedArray() throws Exception {
        // If checkArray validates that all rows have same length
        long[][] counts = {
            {10, 20},
            {30}
        };
        testInstance.chiSquareTest(counts);
    }

    /**
     * Test with a table where one dimension is 1.
     * df = (1-1) * (n-1) = 0.
     */
    @Test
    public void testChiSquareTest_OneDimensionIsOne() throws Exception {
        long[][] counts = {{10, 20, 30}};
        try {
            double pValue = testInstance.chiSquareTest(counts);
            assertTrue(pValue >= 0.0 && pValue <= 1.0);
        } catch (Exception e) {
            // Depending on ChiSquaredDistribution implementation for df=0
        }
    }

    /**
     * Test with a custom distribution to verify the method uses the distribution correctly.
     */
    @Test
    public void testChiSquareTest_WithCustomDistribution() throws Exception {
        // Using a distribution that will return a known value
        // We use a mock-like approach by providing a real distribution
        ChiSquaredDistribution dist = new ChiSquaredDistribution(5.0);
        ChiSquareTestImpl customInstance = new ChiSquareTestImpl(dist);

        long[][] counts = {
            {10, 20},
            {20, 10}
        };
        // df = (2-1)*(2-1) = 1
        // chiSquare(counts) calculation:
        // Total = 60. Expected if no association: row sums: 30, 30; col sums: 30, 30.
        // Expected: 15, 15, 15, 15.
        // ChiSq = sum((O-E)^2/E) = (10-15)^2/15 + (20-15)^2/15 + (20-15)^2/15 + (10-15)^2/15
        // = 25/15 * 4 = 5/3 * 4 = 20/3 = 6.666...

        double pValue = customInstance.chiSquareTest(counts);
        // The method should have set distribution df to 1 (from df calculation)
        // and returned 1 - dist.cumulativeProbability(6.666)
        // Note: the constructor sets df=5, but the method calls distribution.setDegreesOfFreedom(df)
        // So the distribution inside becomes df=1.

        assertTrue(pValue >= 0.0 && pValue <= 1.0);
    }
}
